def transform(grid):
    h, w = len(grid), len(grid[0])
    observed = [(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    candidates = []
    axes = {'row': lambda r,c:r, 'col':lambda r,c:c, 'diag_down':lambda r,c:c-r, 'diag_up':lambda r,c:c+r}
    for name, coord in axes.items():
        for period in range(1, max(h,w)+1):
            values = {}
            ok = True
            for r,c,v in observed:
                residue = coord(r,c) % period
                if residue in values and values[residue] != v:
                    ok = False
                    break
                values[residue] = v
            if ok and len(values) == period:
                candidates.append((period, -len(observed), name, coord, values))
                break
    if not candidates:
        raise ValueError('No complete periodic stripe model')
    period, _, name, coord, values = min(candidates, key=lambda x:(x[0],x[1]))
    return [[values[coord(r,c)%period] for c in range(w)] for r in range(h)]

